  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਹਾਤਮਾ ਬੁੱਧ ਦੇ ਸੁਭਾਅ ਅਤੇ ਉਹਨਾਂ ਦੇ ਲੋਕਾਂ ਪ੍ਰਤੀ ਵਤੀਰੇ ਦਾ ਵਰਣਨ ਕਰੋ। ਲੋਕ ਉਹਨਾਂ ਕੋਲ ਕਿਹੜੀਆਂ ਉਮੀਦਾਂ ਨਾਲ ਆਉਂਦੇ ਸਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੇ ਪਾਤਰ ਚਿਤਰਣ 'ਤੇ ਵਿਸਥਾਰ ਨਾਲ ਚਰਚਾ ਕਰੋ। ਉਸਦੀ ਜ਼ਿੰਦਗੀ ਦੀਆਂ ਮੁਸ਼ਕਲਾਂ ਅਤੇ ਲੋਕਾਂ ਦੇ ਉਸ ਪ੍ਰਤੀ ਵਤੀਰੇ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਨੇ ਬੁੱਧ ਬਾਰੇ ਸੁਣ ਕੇ ਕੀ ਸੋਚਿਆ ਅਤੇ ਉਸਦੇ ਇਸ ਫੈਸਲੇ ਪਿੱਛੇ ਕੀ ਕਾਰਨ ਸਨ? ਉਸਦੀ ਮਾਨਸਿਕ ਸਥਿਤੀ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੀ ਬੁੱਧ ਨਾਲ ਮੁਲਾਕਾਤ ਦਾ ਦ੍ਰਿਸ਼ ਪੇਸ਼ ਕਰੋ। ਉਹ ਕਿਸ ਹਾਲਤ ਵਿੱਚ ਬੁੱਧ ਕੋਲ ਪਹੁੰਚਿਆ ਅਤੇ ਉਸਨੇ ਕੀ ਬੇਨਤੀ ਕੀਤੀ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਿੱਤੇ ਗਏ ਸ਼ਬਦਾਂ 'ਦਇਆ', 'ਰਹਿਮ', 'ਭਿਖਾਰੀ', 'ਅਨਾਥ', 'ਉਪਦੇਸ਼' ਦੇ ਅਰਥਾਂ ਨੂੰ ਸਪੱਸ਼ਟ ਕਰਦੇ ਹੋਏ, ਇਹਨਾਂ ਦੀ ਪਾਠ ਵਿੱਚ ਵਰਤੋਂ ਦੀ ਮਹੱਤਤਾ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਤੋਂ ਤੁਸੀਂ ਕੀ ਸਿੱਖਿਆ ਪ੍ਰਾਪਤ ਕਰਦੇ ਹੋ? ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਵਰਗੇ ਅਨਾਥ ਅਤੇ ਗਰੀਬ ਲੋਕਾਂ ਪ੍ਰਤੀ ਸਮਾਜ ਦਾ ਕੀ ਰਵੱਈਆ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ? ਪਾਠ ਦੇ ਪ੍ਰਸੰਗ ਵਿੱਚ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਹਾਤਮਾ ਬੁੱਧ ਦੇ ਉਪਦੇਸ਼ਾਂ ਦਾ ਸਮਕਾਲੀ ਸਮਾਜ ਵਿੱਚ ਕੀ ਮਹੱਤਵ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਕਰ ਤੁਸੀਂ ਕਿਸ਼ਨ ਦੀ ਥਾਂ ਹੁੰਦੇ ਤਾਂ ਆਪਣੀ ਗਰੀਬੀ ਅਤੇ ਲੋਕਾਂ ਦੇ ਤਾਹਨਿਆਂ ਦਾ ਸਾਹਮਣਾ ਕਿਵੇਂ ਕਰਦੇ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
