  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੀ ਜ਼ਿੰਦਗੀ ਵਿੱਚ ਆਏ ਬਦਲਾਅ ਤੋਂ ਪਹਿਲਾਂ ਅਤੇ ਬਾਅਦ ਦੀ ਸਥਿਤੀ ਦਾ ਤੁਲਨਾਤਮਕ ਅਧਿਐਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਹਾਣੀ ਦੇ ਅੰਤ ਵਿੱਚ ਬੁੱਧ ਦੀ ਸਿੱਖਿਆ ਦਾ ਕੀ ਪ੍ਰਭਾਵ ਪਿਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਦਾ ਸਿਰਲੇਖ 'ਮਿਹਨਤ ਦਾ ਫਲ' ਜਾਂ 'ਸਵੈ-ਨਿਰਭਰਤਾ' ਕਿਉਂ ਢੁਕਵਾਂ ਹੋ ਸਕਦਾ ਹੈ? ਆਪਣੇ ਵਿਚਾਰ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੇ ਰੁੱਖ ਦੀ ਵਾਧੇ ਦੀ ਪ੍ਰਕਿਰਿਆ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੇ ਮਨੋਭਾਵਾਂ ਵਿੱਚ ਆਏ ਬਦਲਾਅ ਨੂੰ ਉਦਾਹਰਣਾਂ ਸਹਿਤ ਸਪੱਸ਼ਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
