  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੀ ਕਹਾਣੀ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਹੋਰ ਲੋਕਾਂ ਦੇ ਜੀਵਨ ਵਿੱਚ ਕੀ ਬਦਲਾਅ ਆਇਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਹਾਣੀ ਵਿੱਚ ਵਰਤੇ ਗਏ ਮੁਹਾਵਰੇ 'ਹੱਥੋਂ-ਹੱਥ ਵਿਕ ਗਏ' ਦਾ ਕੀ ਅਰਥ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਹਾਣੀ ਵਿੱਚ 'ਖੁਸ਼ੀ ਵਿੱਚ ਖੀਵਾ ਹੋਇਆ' ਦਾ ਕੀ ਮਤਲਬ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੇ ਕਾਰੋਬਾਰ ਦੇ ਵਧਣ ਨਾਲ ਉਸਦੇ ਆਲੇ-ਦੁਆਲੇ ਦੇ ਲੋਕਾਂ ਦਾ ਉਸ ਪ੍ਰਤੀ ਰਵੱਈਆ ਕਿਵੇਂ ਬਦਲਿਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁੱਧ ਨੇ ਕਿਸ਼ਨ ਨੂੰ ਸਿਰਫ਼ ਇੱਕ ਦਿਨ ਦੀ ਰੋਟੀ ਦੇਣ ਦੀ ਬਜਾਏ ਕੀ ਸਿਖਾਇਆ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਕਹਾਣੀ ਨੂੰ ਪੜ੍ਹ ਕੇ ਤੁਸੀਂ ਆਪਣੇ ਜੀਵਨ ਵਿੱਚ ਕਿਹੜੇ ਸਿਧਾਂਤ ਅਪਣਾਉਣਾ ਚਾਹੋਗੇ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਹਾਣੀ ਦੇ ਸ਼ੁਰੂਆਤੀ ਹਿੱਸੇ ਵਿੱਚ ਕਿਸ਼ਨ ਦੀ ਸਥਿਤੀ ਦਾ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਮੁੱਖ ਸਿੱਖਣ ਨਤੀਜਿਆਂ ਬਾਰੇ ਵਿਸਥਾਰ ਨਾਲ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਨੇ ਜੀਵਨ ਬਾਰੇ ਕੀ ਮਹੱਤਵਪੂਰਨ ਸਿੱਖਿਆ ਪ੍ਰਾਪਤ ਕੀਤੀ ਅਤੇ ਉਸਨੇ ਇਹ ਸਿੱਖਿਆ ਬੱਚਿਆਂ ਨਾਲ ਕਿਵੇਂ ਸਾਂਝੀ ਕੀਤੀ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਸਿਰਫ਼ ਮੰਗਣ ਨਾਲ ਸੁੱਖ ਨਹੀਂ ਮਿਲਦਾ' - ਇਸ ਕਥਨ ਦੀ ਵਿਆਖਿਆ ਪਾਠ ਦੇ ਪ੍ਰਸੰਗ ਵਿੱਚ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਧੀਰਜ ਅਤੇ ਮਿਹਨਤ' ਮਨੁੱਖੀ ਜੀਵਨ ਨੂੰ ਕਿਵੇਂ ਸੁੰਦਰ ਬਣਾਉਂਦੇ ਹਨ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਤੁਹਾਡੇ ਵਿਚਾਰ ਅਨੁਸਾਰ, ਕਿਸੇ ਦੀ ਮਦਦ ਕਰਨ ਦਾ ਸਭ ਤੋਂ ਉੱਤਮ ਤਰੀਕਾ ਕੀ ਹੈ? ਪਾਠ ਵਿੱਚ ਦਿੱਤੇ ਪ੍ਰਸ਼ਨ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਆਪਣੇ ਵਿਚਾਰ ਪ੍ਰਗਟ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਿੱਤੀ ਗਈ ਕਿਸ਼ਨ ਦੀ ਕਹਾਣੀ ਦਾ ਕੇਂਦਰੀ ਭਾਵ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦਾ ਪਾਠ ਪੁਸਤਕਾਂ 'ਤੇ ਕੀ ਪ੍ਰਭਾਵ ਪੈਂਦਾ ਹੈ? ਇਸ ਪਾਠ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੇ ਚਰਿੱਤਰ ਚਿਤਰਣ ਬਾਰੇ ਲਿਖੋ। ਉਹ ਪਾਠ ਵਿੱਚ ਕਿਹੋ ਜਿਹਾ ਵਿਅਕਤੀ ਪ੍ਰਤੀਤ ਹੁੰਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਰੁੱਖ ਦੀ ਕੀ ਮਹੱਤਤਾ ਦਰਸਾਈ ਗਈ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਸਮਝ ਦੀ ਪਰਖ' ਸਿਰਲੇਖ ਹੇਠ ਦਿੱਤੇ ਪ੍ਰਸ਼ਨਾਂ ਦਾ ਉਦੇਸ਼ ਕੀ ਹੈ? ਵਿਦਿਆਰਥੀਆਂ ਲਈ ਇਹ ਕਿਉਂ ਜ਼ਰੂਰੀ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੀਵਨ ਵਿੱਚ ਧੀਰਜ ਅਤੇ ਲਗਾਤਾਰ ਮਿਹਨਤ ਦੀ ਲੋੜ ਕਿਉਂ ਪੈਂਦੀ ਹੈ? ਵਿਸਥਾਰ ਨਾਲ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਹਾਤਮਾ ਬੁੱਧ ਦੇ ਵਿਚਾਰਾਂ ਦਾ ਪਾਠ ਦੇ ਸੰਦੇਸ਼ ਨਾਲ ਕੀ ਸੰਬੰਧ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਵਰਤੇ ਗਏ ਕਿਸੇ ਇੱਕ ਔਖੇ ਸ਼ਬਦ (ਜਿਵੇਂ 'ਧੀਰਜ' ਜਾਂ 'ਮਿਹਨਤ') ਦਾ ਅਰਥ ਸਪੱਸ਼ਟ ਕਰਦੇ ਹੋਏ, ਉਸਦੀ ਮਹੱਤਤਾ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਬੱਚਿਆਂ ਅਤੇ ਕਿਸ਼ਨ ਦੇ ਆਪਸੀ ਸੰਬੰਧਾਂ ਨੂੰ ਕਿਵੇਂ ਦਰਸਾਇਆ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦਾ ਸਿਰਲੇਖ 'ਪੰਜਾਬੀ ਪਾਠ-ਮਾਲਾ' ਹੈ। ਕੀ ਇਹ ਸਿਰਲੇਖ ਪਾਠ ਦੇ ਵਿਸ਼ੇ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ? ਆਪਣੇ ਵਿਚਾਰ ਦਿਓ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਿੱਤੇ ਗਏ ਨੈਤਿਕ ਮੁੱਲਾਂ ਦੀ ਸੂਚੀ ਬਣਾਓ ਅਤੇ ਹਰੇਕ ਦੀ ਸੰਖੇਪ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਦੀ ਕਹਾਣੀ ਤੋਂ ਤੁਸੀਂ ਆਪਣੇ ਜੀਵਨ ਲਈ ਕਿਹੜੀ ਪ੍ਰੇਰਨਾ ਲੈਂਦੇ ਹੋ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਬੀਜ ਵੀ ਰੁੱਖ ਬਣਦਾ ਹੈ' - ਇਸ ਕਥਨ ਦਾ ਡੂੰਘਾ ਅਰਥ ਕੀ ਹੈ ਅਤੇ ਇਹ ਮਨੁੱਖੀ ਜੀਵਨ 'ਤੇ ਕਿਵੇਂ ਲਾਗੂ ਹੁੰਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ 'ਸੁੱਖ' ਦੀ ਧਾਰਨਾ ਨੂੰ ਕਿਵੇਂ ਪੇਸ਼ ਕੀਤਾ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੇਕਰ ਕਿਸ਼ਨ ਨੇ ਆਪਣੀ ਸੋਚ ਨਾ ਬਦਲੀ ਹੁੰਦੀ ਤਾਂ ਉਸਦੀ ਜ਼ਿੰਦਗੀ ਕਿਹੋ ਜਿਹੀ ਹੁੰਦੀ? ਕਲਪਨਾ ਕਰਕੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
