  ('36c3bca9-40d6-4981-80fc-4981b91c58c4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੁੱਧ ਨੇ ਉਸਨੂੰ ਪਿਆਰ ਨਾਲ ਬਿਠਾਇਆ। ਉਹ ਬੋਲੇ, "ਬੇਟਾ! ਤੈਨੂੰ ਦੋ ਭੁੱਖਾਂ ਸਤਾ ਰਹੀਆਂ ਹਨ—ਪੇਟ ਦੀ ਭੁੱਖ ਅਤੇ ਮਨ ਦੀ ਭੁੱਖ। ਪੇਟ ਦੀ ਭੁੱਖ ਰੋਟੀ ਨਾਲ ਮਿਟ ਸਕਦੀ ਹੈ ਪਰ ਮਨ ਦੀ ਭੁੱਖ ਸਿਰਫ਼ ਮਿਹਨਤ ਅਤੇ ਸੱਚਾਈ ਨਾਲ ਹੀ ਸ਼ਾਂਤ ਹੋ ਸਕਦੀ ਹੈ।"$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f31f083c-e097-495d-85a6-6d7babad75a8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਨੇ ਰੋਂਦੇ ਹੋਏ ਕਿਹਾ, "ਪਰ ਪ੍ਰਭੂ ਮੇਰੇ ਕੋਲ ਨਾ ਜ਼ਮੀਨ ਹੈ ਨਾ ਘਰ, ਨਾ ਹੀ ਕੋਈ ਸਹਾਰਾ। ਮੈਂ ਕਿਵੇਂ ਮਿਹਨਤ ਕਰਾਂਗਾ?" ਬੁੱਧ ਨੇ ਆਪਣੇ ਹੱਥ ਵਿੱਚੋਂ ਇੱਕ ਛੋਟਾ ਬੀਜ ਕੱਢਿਆ। ਉਹ ਉਸਦੀ ਹਥੇਲੀ ਉੱਤੇ ਰੱਖ ਕੇ ਬੋਲੇ, "ਇਹ ਬੀਜ ਤੇਰੇ ਲਈ ਉਮੀਦ ਦਾ ਰਾਹ ਹੈ।"$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0c8341b4-9c3d-4858-baba-f03bc20d9e54', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸਨੂੰ ਮਿੱਟੀ ਵਿੱਚ ਬੀਜ ਦੇ। ਪਾਣੀ ਦੇਣਾ, ਸੰਭਾਲ ਕਰਨੀ, ਧੀਰਜ ਰੱਖਣਾ। ਜਦ ਇਹ ਵੱਡਾ ਹੋਵੇਗਾ, ਤੈਨੂੰ ਫਲ ਮਿਲਣਗੇ। ਉਹ ਫਲ ਤੇਰਾ ਪੇਟ ਭਰਨਗੇ ਤੇ ਤੈਨੂੰ ਰੋਜ਼ੀ ਦੇਣਗੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('285ca7bd-973c-40ed-b471-512ab5ad0313', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਇਹ ਸੁਣ ਕੇ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਸਨੇ ਸੋਚਿਆ, "ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਮੇਰੀ ਕਿਸਮਤ ਕਿਵੇਂ ਬਦਲ ਸਕਦਾ ਹੈ?" ਬੁੱਧ ਦੇ ਕੋਲ ਬੈਠੇ ਲੋਕਾਂ ਨੇ ਵੀ ਮੂੰਹ ਉੱਤੇ ਹੱਥ ਰੱਖ ਕੇ ਆਪਣਾ ਹਾਸਾ ਮਸਾਂ ਰੋਕਿਆ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
