  ('5fe58176-2dc9-4896-8ce2-85a6c5f0e2c6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਬੁੱਧ ਦੇ ਸ਼ਬਦ ਕਿਸ਼ਨ ਦੇ ਦਿਲ ਵਿੱਚ ਵਸ ਗਏ। ਉਸਨੇ ਬੀਜ ਲਿਆ ਤੇ ਆਪਣੇ ਪਿੰਡ ਵਾਪਸ ਆ ਗਿਆ। ਜਦੋਂ ਲੋਕਾਂ ਨੇ ਵੇਖਿਆ ਕਿ ਉਹ ਬੀਜ ਬੀਜ ਰਿਹਾ ਹੈ ਤਾਂ ਸਭ ਉਸਨੂੰ ਮਖੌਲ ਕਰਨ ਲੱਗੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0c3f3163-aef3-46c9-a56b-5bdcc766bfcf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੋਈ ਕਹਿੰਦਾ, "ਇਹ ਤਾਂ ਪਾਗਲ ਹੋ ਗਿਆ ਹੈ।" ਕੋਈ ਕਹਿੰਦਾ, "ਬੁੱਧ ਨੇ ਇਸਨੂੰ ਧੋਖਾ ਦੇ ਦਿੱਤਾ ਹੈ।" ਪਰ ਕਿਸ਼ਨ ਨੇ ਕਿਸੇ ਦੀ ਗੱਲ ਨਾ ਸੁਣੀ। ਉਹ ਹਰ ਰੋਜ਼ ਬੀਜ ਨੂੰ ਪਾਣੀ ਦਿੰਦਾ, ਮਿੱਟੀ ਦੀ ਖੁਦਾਈ ਕਰਦਾ ਤੇ ਉਸਨੂੰ ਪਿਆਰ ਨਾਲ ਵੇਖਦਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('4a8bc1cf-7edb-4e5a-a2fc-bc6acbf361ca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੁਝ ਦਿਨਾਂ ਬਾਅਦ ਮਿੱਟੀ ਵਿੱਚੋਂ ਇੱਕ ਨਿੱਕੀ-ਜਿਹੀ ਹਰੀ ਪੱਤੀ ਨਿਕਲੀ। ਕਿਸ਼ਨ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਖੁਸ਼ੀ ਦੇ ਹੰਝੂ ਆ ਗਏ। ਉਸਨੇ ਸੋਚਿਆ, "ਕੀ ਬੁੱਧ ਸਹੀ ਕਹਿੰਦੇ ਸਨ? ਇਹ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਪੁੰਗਰ ਕੇ ਮੇਰਾ ਜੀਵਨ ਕਿਵੇਂ ਸੁਧਾਰ ਸਕਦਾ ਹੈ?"$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('44efdf80-0ef5-456a-a8fb-3fac6bc9b8dc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਲੋਕਾਂ ਦੇ ਦਰਾਂ ਉੱਤੇ ਮੰਗਦਾ ਹਾਂ। ਕਦੇ ਰੋਟੀ ਮਿਲ ਜਾਂਦੀ ਹੈ ਤੇ ਕਦੇ ਨਹੀਂ ਪਰ ਪਾਪੀ ਪੇਟ ਨੂੰ ਤਾਂ ਥੋੜ੍ਹੇ ਸਮੇਂ ਬਾਅਦ ਭੋਜਨ ਚਾਹੀਦਾ ਹੀ ਹੈ। ਮੇਰੇ ਲਈ ਕੋਈ ਰਾਹ ਦੱਸੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
