  ('84f76a1a-9d8b-47a3-a3ef-ea17ef7e799c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਨਾਥ - ਜਿਸ ਦੇ ਮਾਤਾ-ਪਿਤਾ ਮਰ ਚੁੱਕੇ ਹੋਣ (orphan)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f9d746d1-911a-41fd-a4c1-8cdd9fc12dda', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਲੋਕਾਂ ਦੇ ਦਰਾਂ ਉੱਤੇ ਮੰਗਦਾ ਹਾਂ। ਕਦੇ ਰੋਟੀ ਮਿਲ ਜਾਂਦੀ ਹੈ ਤੇ ਕਦੇ ਨਹੀਂ ਪਰ ਪਾਪੀ ਪੇਟ ਨੂੰ ਤਾਂ ਥੋੜ੍ਹੇ ਸਮੇਂ ਬਾਅਦ ਭੋਜਨ ਚਾਹੀਦਾ ਹੀ ਹੈ। ਮੇਰੇ ਲਈ ਕੋਈ ਰਾਹ ਦੱਸੋ। ਮੈਨੂੰ ਕੁਝ ਰੋਟੀਆਂ ਦਾਨ ਦਿਓ।" ਬੁੱਧ ਨੇ ਉਸਨੂੰ ਪਿਆਰ ਨਾਲ ਬਿਠਾਇਆ। ਉਹ ਬੋਲੇ, "ਬੇਟਾ! ਤੈਨੂੰ ਦੋ ਭੁੱਖਾਂ ਸਤਾ ਰਹੀਆਂ ਹਨ—ਪੇਟ ਦੀ ਭੁੱਖ ਅਤੇ ਮਨ ਦੀ ਭੁੱਖ। ਪੇਟ ਦੀ ਭੁੱਖ ਰੋਟੀ ਨਾਲ ਮਿਟ ਸਕਦੀ ਹੈ ਪਰ ਮਨ ਦੀ ਭੁੱਖ ਸਿਰਫ਼ ਮਿਹਨਤ ਅਤੇ ਸੱਚਾਈ ਨਾਲ ਹੀ ਸ਼ਾਂਤ ਹੋ ਸਕਦੀ ਹੈ।"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('23528ff7-7383-4935-8d61-9668f4835610', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਨੇ ਰੋਂਦੇ ਹੋਏ ਕਿਹਾ, "ਪਰ ਪ੍ਰਭੂ ਮੇਰੇ ਕੋਲ ਨਾ ਜ਼ਮੀਨ ਹੈ ਨਾ ਘਰ, ਨਾ ਹੀ ਕੋਈ ਸਹਾਰਾ। ਮੈਂ ਕਿਵੇਂ ਮਿਹਨਤ ਕਰਾਂਗਾ?" ਬੁੱਧ ਨੇ ਆਪਣੇ ਹੱਥ ਵਿੱਚੋਂ ਇੱਕ ਛੋਟਾ ਬੀਜ ਕੱਢਿਆ। ਉਹ ਉਸਦੀ ਹਥੇਲੀ ਉੱਤੇ ਰੱਖ ਕੇ ਬੋਲੇ, "ਇਹ ਬੀਜ ਤੇਰੇ ਲਈ ਉਮੀਦ ਦਾ ਰਾਹ ਹੈ। ਇਸਨੂੰ ਮਿੱਟੀ ਵਿੱਚ ਬੀਜ ਦੇ। ਪਾਣੀ ਦੇਣਾ, ਸੰਭਾਲ ਕਰਨੀ, ਧੀਰਜ ਰੱਖਣਾ। ਜਦ ਇਹ ਵੱਡਾ ਹੋਵੇਗਾ, ਤੈਨੂੰ ਫਲ ਮਿਲਣਗੇ। ਉਹ ਫਲ ਤੇਰਾ ਪੇਟ ਭਰਨਗੇ ਤੇ ਤੈਨੂੰ ਰੋਜ਼ੀ ਦੇਣਗੇ।"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('49e1a6a5-9127-4dbd-9a66-4ccc287d773b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਿਸ਼ਨ ਇਹ ਸੁਣ ਕੇ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਸਨੇ ਸੋਚਿਆ, "ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਮੇਰੀ ਕਿਸਮਤ ਕਿਵੇਂ ਬਦਲ ਸਕਦਾ ਹੈ?" ਬੁੱਧ ਦੇ ਕੋਲ ਬੈਠੇ ਲੋਕਾਂ ਨੇ ਵੀ ਮੂੰਹ ਉੱਤੇ ਹੱਥ ਰੱਖ ਕੇ ਆਪਣਾ ਹਾਸਾ ਮਸਾਂ ਰੋਕਿਆ। ਪਰ ਬੁੱਧ ਦੇ ਸ਼ਬਦ ਕਿਸ਼ਨ ਦੇ ਦਿਲ ਵਿੱਚ ਵਸ ਗਏ। ਉਸਨੇ ਬੀਜ ਲਿਆ ਤੇ ਆਪਣੇ ਪਿੰਡ ਵਾਪਸ ਆ ਗਿਆ। ਜਦੋਂ ਲੋਕਾਂ ਨੇ ਵੇਖਿਆ ਕਿ ਉਹ ਬੀਜ ਬੀਜ ਰਿਹਾ ਹੈ ਤਾਂ ਸਭ ਉਸਨੂੰ ਮਖੌਲ ਕਰਨ ਲੱਗੇ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('1e7aa894-e42c-4a53-91a3-e371f277fb33', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕੋਈ ਕਹਿੰਦਾ, "ਇਹ ਤਾਂ ਪਾਗਲ ਹੋ ਗਿਆ ਹੈ।" ਕੋਈ ਕਹਿੰਦਾ, "ਬੁੱਧ ਨੇ ਇਸਨੂੰ ਧੋਖਾ ਦੇ ਦਿੱਤਾ ਹੈ।" ਪਰ ਕਿਸ਼ਨ ਨੇ ਕਿਸੇ ਦੀ ਗੱਲ ਨਾ ਸੁਣੀ। ਉਹ ਹਰ ਰੋਜ਼ ਬੀਜ ਨੂੰ ਪਾਣੀ ਦਿੰਦਾ, ਮਿੱਟੀ ਦੀ ਖੁਦਾਈ ਕਰਦਾ ਤੇ ਉਸਨੂੰ ਪਿਆਰ ਨਾਲ ਵੇਖਦਾ। ਕੁਝ ਦਿਨਾਂ ਬਾਅਦ ਮਿੱਟੀ ਵਿੱਚੋਂ ਇੱਕ ਨਿੱਕੀ-ਜਿਹੀ ਹਰੀ ਪੱਤੀ ਨਿਕਲੀ। ਕਿਸ਼ਨ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਖੁਸ਼ੀ ਦੇ ਹੰਝੂ ਆ ਗਏ। ਉਸਨੇ ਸੋਚਿਆ, "ਕੀ ਬੁੱਧ ਸਹੀ ਕਹਿੰਦੇ ਸਨ? ਇਹ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਪੁੰਗਰ ਕੇ ਮੇਰਾ ਜੀਵਨ ਕਿਵੇਂ ਸੁਧਾਰ ਸਕਦਾ ਹੈ?"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f97e47a1-be34-4a25-a730-a5ac6a20ad3b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '03f7e1b1-b013-475b-854c-46c231c1ddec', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਲੋਕਾਂ ਦੇ ਦਰਾਂ ਉੱਤੇ ਮੰਗਦਾ ਹਾਂ। ਕਦੇ ਰੋਟੀ ਮਿਲ ਜਾਂਦੀ ਹੈ ਤੇ ਕਦੇ ਨਹੀਂ ਪਰ ਪਾਪੀ ਪੇਟ ਨੂੰ ਤਾਂ ਥੋੜ੍ਹੇ ਸਮੇਂ ਬਾਅਦ ਭੋਜਨ ਚਾਹੀਦਾ ਹੀ ਹੈ। ਮੇਰੇ ਲਈ ਕੋਈ ਰਾਹ ਦੱਸੋ। ਮੈਨੂੰ ਕੁਝ ਰੋਟੀਆਂ ਦਾਨ ਦਿਓ।" ਬੁੱਧ ਨੇ ਉਸਨੂੰ ਪਿਆਰ ਨਾਲ ਬਿਠਾਇਆ। ਉਹ ਬੋਲੇ, "ਬੇਟਾ! ਤੈਨੂੰ ਦੋ ਭੁੱਖਾਂ ਸਤਾ ਰਹੀਆਂ ਹਨ—ਪੇਟ ਦੀ ਭੁੱਖ ਅਤੇ ਮਨ ਦੀ ਭੁੱਖ। ਪੇਟ ਦੀ ਭੁੱਖ ਰੋਟੀ ਨਾਲ ਮਿਟ ਸਕਦੀ ਹੈ ਪਰ ਮਨ ਦੀ ਭੁੱਖ ਸਿਰਫ਼ ਮਿਹਨਤ ਅਤੇ ਸੱਚਾਈ ਨਾਲ ਹੀ ਸ਼ਾਂਤ ਹੋ ਸਕਦੀ ਹੈ।" ਕਿਸ਼ਨ ਨੇ ਰੋਂਦੇ ਹੋਏ ਕਿਹਾ, "ਪਰ ਪ੍ਰਭੂ ਮੇਰੇ ਕੋਲ ਨਾ ਜ਼ਮੀਨ ਹੈ ਨਾ ਘਰ, ਨਾ ਹੀ ਕੋਈ ਸਹਾਰਾ। ਮੈਂ ਕਿਵੇਂ ਮਿਹਨਤ ਕਰਾਂਗਾ?" ਬੁੱਧ ਨੇ ਆਪਣੇ ਹੱਥ ਵਿੱਚੋਂ ਇੱਕ ਛੋਟਾ ਬੀਜ ਕੱਢਿਆ। ਉਹ ਉਸਦੀ ਹਥੇਲੀ ਉੱਤੇ ਰੱਖ ਕੇ ਬੋਲੇ, "ਇਹ ਬੀਜ ਤੇਰੇ ਲਈ ਉਮੀਦ ਦਾ ਰਾਹ ਹੈ। ਇਸਨੂੰ ਮਿੱਟੀ ਵਿੱਚ ਬੀਜ ਦੇ। ਪਾਣੀ ਦੇਣਾ, ਸੰਭਾਲ ਕਰਨੀ, ਧੀਰਜ ਰੱਖਣਾ। ਜਦ ਇਹ ਵੱਡਾ ਹੋਵੇਗਾ, ਤੈਨੂੰ ਫਲ ਮਿਲਣਗੇ। ਉਹ ਫਲ ਤੇਰਾ ਪੇਟ ਭਰਨਗੇ ਤੇ ਤੈਨੂੰ ਰੋਜ਼ੀ ਦੇਣਗੇ।" ਕਿਸ਼ਨ ਇਹ ਸੁਣ ਕੇ ਹੈਰਾਨ ਹੋ ਗਿਆ। ਉਸਨੇ ਸੋਚਿਆ, "ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਮੇਰੀ ਕਿਸਮਤ ਕਿਵੇਂ ਬਦਲ ਸਕਦਾ ਹੈ?" ਬੁੱਧ ਦੇ ਕੋਲ ਬੈਠੇ ਲੋਕਾਂ ਨੇ ਵੀ ਮੂੰਹ ਉੱਤੇ ਹੱਥ ਰੱਖ ਕੇ ਆਪਣਾ ਹਾਸਾ ਮਸਾਂ ਰੋਕਿਆ। ਪਰ ਬੁੱਧ ਦੇ ਸ਼ਬਦ ਕਿਸ਼ਨ ਦੇ ਦਿਲ ਵਿੱਚ ਵਸ ਗਏ। ਉਸਨੇ ਬੀਜ ਲਿਆ ਤੇ ਆਪਣੇ ਪਿੰਡ ਵਾਪਸ ਆ ਗਿਆ। ਜਦੋਂ ਲੋਕਾਂ ਨੇ ਵੇਖਿਆ ਕਿ ਉਹ ਬੀਜ ਬੀਜ ਰਿਹਾ ਹੈ ਤਾਂ ਸਭ ਉਸਨੂੰ ਮਖੌਲ ਕਰਨ ਲੱਗੇ। ਕੋਈ ਕਹਿੰਦਾ, "ਇਹ ਤਾਂ ਪਾਗਲ ਹੋ ਗਿਆ ਹੈ।" ਕੋਈ ਕਹਿੰਦਾ, "ਬੁੱਧ ਨੇ ਇਸਨੂੰ ਧੋਖਾ ਦੇ ਦਿੱਤਾ ਹੈ।" ਪਰ ਕਿਸ਼ਨ ਨੇ ਕਿਸੇ ਦੀ ਗੱਲ ਨਾ ਸੁਣੀ। ਉਹ ਹਰ ਰੋਜ਼ ਬੀਜ ਨੂੰ ਪਾਣੀ ਦਿੰਦਾ, ਮਿੱਟੀ ਦੀ ਖੁਦਾਈ ਕਰਦਾ ਤੇ ਉਸਨੂੰ ਪਿਆਰ ਨਾਲ ਵੇਖਦਾ। ਕੁਝ ਦਿਨਾਂ ਬਾਅਦ ਮਿੱਟੀ ਵਿੱਚੋਂ ਇੱਕ ਨਿੱਕੀ-ਜਿਹੀ ਹਰੀ ਪੱਤੀ ਨਿਕਲੀ। ਕਿਸ਼ਨ ਦੀਆਂ ਅੱਖਾਂ ਵਿੱਚ ਖੁਸ਼ੀ ਦੇ ਹੰਝੂ ਆ ਗਏ। ਉਸਨੇ ਸੋਚਿਆ, "ਕੀ ਬੁੱਧ ਸਹੀ ਕਹਿੰਦੇ ਸਨ? ਇਹ ਛੋਟਾ ਜਿਹਾ ਬੀਜ ਪੁੰਗਰ ਕੇ ਮੇਰਾ ਜੀਵਨ ਕਿਵੇਂ ਸੁਧਾਰ ਸਕਦਾ ਹੈ?"$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-191Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
